import fs from 'fs';
import path from 'path';

/**
 * Utility to write code generated by agents to the local filesystem.
 */
export const writeGeneratedCode = (actionsText: string, projectName: string) => {
  const outputDir = path.join(process.cwd(), 'generated-code', projectName.replace(/\s+/g, '-').toLowerCase());
  
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Regex to find markdown code blocks with filenames in the format:
  // FILE: path/to/file.ext
  // ```lang
  // code
  // ```
  const fileRegex = /FILE:\s*([^\n]+)\n```[a-z]*\n([\s\S]*?)```/gi;
  let match;
  const writtenFiles: string[] = [];

  while ((match = fileRegex.exec(actionsText)) !== null) {
    const filePath = match[1].trim();
    const code = match[2];
    const fullPath = path.join(outputDir, filePath);

    const dir = path.dirname(fullPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    fs.writeFileSync(fullPath, code);
    writtenFiles.push(filePath);
  }

  return writtenFiles;
};
